class Schema(BaseSchema, metaclass=SchemaMeta):
    __doc__ = BaseSchema.__doc__

    @classmethod
    def from_dict(cls, fields, *, name="GeneratedSchema", **kwargs):
        """Generate a Schema class from a dictionary of fields.

        :param dict fields: Dictionary of field name -> `Field` pairs.
        :param str name: Name of the generated Schema class.
        :param dict kwargs: Additional attributes/methods to pass to the generated class.
        :return: A generated `Schema` class.
        """
        return type(name, (cls,), {**fields, **kwargs})

def test_from_dict():
    MyDynamicSchema = Schema.from_dict({"foo": fields.Str()}, name="CustomName")
    assert MyDynamicSchema.__name__ == "CustomName"
    schema = MyDynamicSchema()
    assert "foo" in schema.fields

    res = schema.load({"foo": "bar"})
    assert res == {"foo": "bar"}

    with pytest.raises(ValidationError):
        schema.load({"foo": 123})

def test_nested_from_dict():
    class AlbumSchema(Schema):
        artist = fields.Nested(Schema.from_dict({"name": fields.Str()}))

    schema = AlbumSchema()
    res = schema.load({"artist": {"name": "Queen"}})
    assert res == {"artist": {"name": "Queen"}}

